import React from "react"
import { Link } from "gatsby"

import GamePlayerFrame from "../components/game/GamePlayerFrame"
import AdSlot from "../components/home/AdSlot"
import GameCard from "../components/home/GameCard"
import SectionHeading from "../components/home/SectionHeading"
import Layout from "../components/layout/Layout"
import Seo from "../components/Seo"
import { gamesCatalog, getGameBySlug } from "../data/games"

function GameDetailTemplate({ pageContext }) {
  const game = getGameBySlug(pageContext.slug)

  if (!game) {
    return (
      <Layout>
        <div className="mx-auto flex min-h-screen max-w-3xl items-center justify-center px-6">
          <div className="arcade-panel p-8 text-center">
            <p className="text-sm font-medium text-slate-600">Game not found.</p>
            <div className="mt-4">
              <Link to="/games" className="solid-button">
                Back to library
              </Link>
            </div>
          </div>
        </div>
      </Layout>
    )
  }

  const relatedGames = gamesCatalog
    .filter((candidate) => candidate.slug !== game.slug)
    .slice(0, 3)

  return (
    <Layout>
      <div className="relative">
        <div className="mesh-dot left-[8%] top-20 h-24 w-24 bg-[#1452ff]/25" />
        <div className="mesh-dot right-[10%] top-[24rem] h-28 w-28 bg-[#ff693d]/28" />

        <header className="mx-auto max-w-7xl px-4 pb-6 pt-5 sm:px-6 lg:px-8">
          <div className="arcade-panel px-4 py-3 sm:px-6">
            <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
              <div className="flex flex-wrap items-center gap-3">
                <Link to="/" className="display-heading text-xl text-slate-900 sm:text-2xl">
                  Launchpad Arcade
                </Link>
                <span className="rounded-full bg-[#cbff52] px-3 py-1 text-[11px] font-bold uppercase tracking-[0.22em] text-slate-900">
                  Game detail
                </span>
              </div>
              <div className="flex flex-wrap items-center gap-3">
                <Link to="/" className="ghost-button px-5 py-2.5 text-xs sm:text-sm">
                  Home
                </Link>
                <Link to="/games" className="solid-button px-5 py-2.5 text-xs sm:text-sm">
                  Game library
                </Link>
              </div>
            </div>
          </div>
        </header>

        <main className="mx-auto max-w-7xl px-4 pb-20 sm:px-6 lg:px-8">
          <section className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
            <div className="arcade-panel p-7 sm:p-10">
              <span className="eyebrow-label">{game.genre}</span>
              <h1 className="display-heading mt-6 text-4xl leading-[1.08] text-slate-900 sm:text-5xl xl:text-6xl">
                {game.title}
              </h1>
              <p className="mt-5 max-w-3xl text-lg leading-8 text-slate-700">{game.tagline}</p>
              <p className="mt-5 max-w-3xl text-base leading-8 text-slate-600">{game.description}</p>

              <div className="mt-8 flex flex-wrap gap-3">
                {game.tags.map((tag) => (
                  <span
                    key={tag}
                    className="rounded-full bg-[#f5eedf] px-4 py-2 text-sm font-medium text-slate-700"
                  >
                    {tag}
                  </span>
                ))}
              </div>

              <div className="mt-8 flex flex-col gap-3 sm:flex-row">
                <a href="#play-stage" className="solid-button">
                  Open play stage
                </a>
                <Link to="/games" className="ghost-button">
                  Browse more games
                </Link>
              </div>
            </div>

            <div className="space-y-6">
              <AdSlot
                label="Detail page leaderboard"
                size="728 x 90"
                note="This slot sits above the play frame and works for launch sponsors or house ads."
                tone="cobalt"
              />

              <div className="arcade-panel p-6">
                <p className="text-[10px] font-bold uppercase tracking-[0.28em] text-slate-500">
                  Quick facts
                </p>
                <div className="mt-5 space-y-4">
                  <div className="rounded-[20px] bg-white/70 px-4 py-4">
                    <p className="text-xs font-bold uppercase tracking-[0.22em] text-slate-500">
                      Session length
                    </p>
                    <p className="mt-2 text-sm font-medium text-slate-900">{game.sessionLabel}</p>
                  </div>
                  <div className="rounded-[20px] bg-white/70 px-4 py-4">
                    <p className="text-xs font-bold uppercase tracking-[0.22em] text-slate-500">
                      Recommended slot
                    </p>
                    <p className="mt-2 text-sm font-medium text-slate-900">{game.slot}</p>
                  </div>
                  <div className="rounded-[20px] bg-white/70 px-4 py-4">
                    <p className="text-xs font-bold uppercase tracking-[0.22em] text-slate-500">
                      Audience
                    </p>
                    <p className="mt-2 text-sm font-medium text-slate-900">{game.audience}</p>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <section
            id="play-stage"
            className="mt-14 grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px] lg:items-start"
          >
            <div className="space-y-6">
              <GamePlayerFrame game={game} />

              <div className="grid gap-4 md:grid-cols-3">
                <div className="arcade-panel p-5">
                  <p className="text-[10px] font-bold uppercase tracking-[0.24em] text-slate-500">
                    Monetization
                  </p>
                  <p className="mt-3 text-sm leading-7 text-slate-700">{game.monetization}</p>
                </div>
                <div className="arcade-panel p-5">
                  <p className="text-[10px] font-bold uppercase tracking-[0.24em] text-slate-500">
                    Sponsor fit
                  </p>
                  <p className="mt-3 text-sm leading-7 text-slate-700">{game.sponsorFit}</p>
                </div>
                <div className="arcade-panel p-5">
                  <p className="text-[10px] font-bold uppercase tracking-[0.24em] text-slate-500">
                    Catalog role
                  </p>
                  <p className="mt-3 text-sm leading-7 text-slate-700">{game.stage}</p>
                </div>
              </div>
            </div>

            <aside className="space-y-6 lg:sticky lg:top-6">
              <div className="arcade-panel p-6">
                <p className="text-[10px] font-bold uppercase tracking-[0.28em] text-slate-500">
                  Controls
                </p>
                <ul className="mt-5 space-y-3">
                  {game.controls.map((control) => (
                    <li
                      key={control}
                      className="rounded-[20px] bg-white/70 px-4 py-4 text-sm font-medium leading-6 text-slate-700"
                    >
                      {control}
                    </li>
                  ))}
                </ul>
              </div>

              <AdSlot
                label="Sidebar medium rectangle"
                size="300 x 250"
                note="Use this unit for evergreen campaigns, sponsor bundles, or internal promotion."
                tone="coral"
              />

              <AdSlot
                label="Tall premium rail"
                size="300 x 600"
                note="Reserve the taller rail for premium detail-page inventory that stays visible while players read."
                tone="lime"
              />
            </aside>
          </section>

          <section className="mt-14 grid gap-6 lg:grid-cols-2">
            <div className="arcade-panel p-6 sm:p-7">
              <span className="eyebrow-label">About this game</span>
              <p className="mt-6 text-base leading-8 text-slate-700">{game.description}</p>
            </div>

            <div className="arcade-panel p-6 sm:p-7">
              <span className="eyebrow-label">Why it works</span>
              <div className="mt-6 space-y-4">
                {game.highlights.map((highlight) => (
                  <div
                    key={highlight}
                    className="rounded-[20px] bg-white/70 px-4 py-4 text-sm font-medium leading-7 text-slate-700"
                  >
                    {highlight}
                  </div>
                ))}
              </div>
            </div>
          </section>

          <section className="mt-14">
            <AdSlot
              label="Post-stage takeover"
              size="970 x 250"
              note="Place a wide sponsor or house-ad unit after the play frame so it lands after players engage with the page."
              tone="neutral"
              className="p-6 sm:p-7"
            />
          </section>

          <section className="mt-14">
            <SectionHeading
              eyebrow="Related games"
              title="Keep players in the catalog after one run."
              description="A strong detail page should hand players to the next game rather than ending in a dead stop."
            />
            <div className="mt-8 grid gap-6 xl:grid-cols-3">
              {relatedGames.map((relatedGame) => (
                <GameCard key={relatedGame.slug} game={relatedGame} />
              ))}
            </div>
          </section>
        </main>
      </div>
    </Layout>
  )
}

export const Head = ({ pageContext }) => {
  const game = getGameBySlug(pageContext.slug)

  if (!game) {
    return <Seo title="Game not found" />
  }

  return <Seo title={game.title} description={game.blurb} />
}

export default GameDetailTemplate
