import React from "react"

const toneClasses = {
  cobalt: "bg-[#edf3ff] border-[#c9d8ff]",
  coral: "bg-[#fff1e8] border-[#ffd2be]",
  lime: "bg-[#f5ffd4] border-[#d7ef88]",
  neutral: "bg-[rgba(255,255,255,0.74)] border-[rgba(27,28,49,0.12)]",
}

function AdSlot({ label, size, note, tone = "neutral", className = "" }) {
  const toneClass = toneClasses[tone] || toneClasses.neutral

  return (
    <div
      className={`arcade-panel border-2 border-dashed p-5 ${toneClass} ${className}`}
    >
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-[10px] font-bold uppercase tracking-[0.28em] text-slate-500">
            Ad inventory
          </p>
          <h3 className="mt-2 text-lg font-bold text-slate-900">{label}</h3>
        </div>
        <span className="rounded-full bg-slate-900 px-3 py-1 text-[11px] font-bold uppercase tracking-[0.22em] text-white">
          {size}
        </span>
      </div>
      <p className="mt-4 max-w-sm text-sm leading-6 text-slate-600">{note}</p>
    </div>
  )
}

export default AdSlot
