import React from "react"

const accentPalette = {
  cobalt: { primary: "#1452ff", secondary: "#7bdcff", surface: "#0e1638" },
  coral: { primary: "#ff693d", secondary: "#ffd25f", surface: "#341812" },
  ink: { primary: "#1b1c31", secondary: "#3bb5d9", surface: "#0e1018" },
  lime: { primary: "#7fdf3b", secondary: "#d8ff62", surface: "#152313" },
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
}

function buildPreviewSrcDoc(game) {
  const palette = accentPalette[game.accent] || accentPalette.cobalt
  const controlsMarkup = game.controls
    .map((control) => `<li>${escapeHtml(control)}</li>`)
    .join("")
  const tagMarkup = game.tags
    .slice(0, 3)
    .map((tag) => `<span>${escapeHtml(tag)}</span>`)
    .join("")

  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(game.title)} Preview</title>
    <style>
      :root {
        --primary: ${palette.primary};
        --secondary: ${palette.secondary};
        --surface: ${palette.surface};
        --ink: #f4f7ff;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        overflow: hidden;
        color: var(--ink);
        font-family: "Segoe UI", Arial, sans-serif;
        background:
          radial-gradient(circle at top right, rgba(255, 255, 255, 0.18), transparent 22%),
          radial-gradient(circle at bottom left, rgba(255, 255, 255, 0.14), transparent 24%),
          linear-gradient(145deg, var(--surface) 0%, color-mix(in srgb, var(--primary) 38%, #08111f) 55%, #05070d 100%);
      }

      body::before,
      body::after {
        content: "";
        position: absolute;
        inset: 0;
        pointer-events: none;
      }

      body::before {
        background:
          linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
          linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
        background-size: 32px 32px;
        mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.95), transparent 82%);
      }

      body::after {
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.05), transparent 28%, rgba(255, 255, 255, 0.03));
        animation: scan 7s linear infinite;
      }

      @keyframes scan {
        0% {
          transform: translateY(-100%);
        }
        100% {
          transform: translateY(100%);
        }
      }

      .frame {
        position: relative;
        width: min(92vw, 1080px);
        min-height: min(72vh, 660px);
        padding: 28px;
        border-radius: 28px;
        border: 1px solid rgba(255, 255, 255, 0.14);
        background: rgba(8, 12, 24, 0.55);
        backdrop-filter: blur(14px);
        box-shadow: 0 24px 80px rgba(0, 0, 0, 0.36);
      }

      .glow {
        position: absolute;
        width: 240px;
        height: 240px;
        border-radius: 999px;
        background: radial-gradient(circle, color-mix(in srgb, var(--secondary) 55%, white), transparent 72%);
        filter: blur(8px);
        opacity: 0.55;
      }

      .glow.one {
        top: -40px;
        right: -30px;
      }

      .glow.two {
        bottom: -80px;
        left: -40px;
        background: radial-gradient(circle, color-mix(in srgb, var(--primary) 60%, white), transparent 72%);
      }

      .topline {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
      }

      .badge {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 10px 14px;
        border-radius: 999px;
        border: 1px solid rgba(255, 255, 255, 0.14);
        background: rgba(255, 255, 255, 0.08);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.28em;
        text-transform: uppercase;
      }

      .hud {
        display: grid;
        gap: 16px;
        margin-top: 28px;
      }

      .meter {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 12px;
      }

      .meter div,
      .panel,
      .controls li,
      .tag-row span {
        border: 1px solid rgba(255, 255, 255, 0.12);
        background: rgba(255, 255, 255, 0.07);
      }

      .meter div {
        border-radius: 18px;
        padding: 14px;
      }

      .meter strong {
        display: block;
        margin-top: 6px;
        font-size: 18px;
      }

      .panel {
        border-radius: 28px;
        padding: 24px;
      }

      .panel h1 {
        margin: 0;
        font-size: clamp(34px, 7vw, 72px);
        line-height: 0.96;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      .panel p {
        max-width: 34rem;
        margin: 18px 0 0;
        color: rgba(244, 247, 255, 0.82);
        font-size: 15px;
        line-height: 1.8;
      }

      .tag-row {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
        margin-top: 20px;
      }

      .tag-row span {
        border-radius: 999px;
        padding: 8px 12px;
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      .controls {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: 12px;
        padding: 0;
        margin: 22px 0 0;
        list-style: none;
      }

      .controls li {
        border-radius: 18px;
        padding: 14px;
        line-height: 1.5;
        font-size: 13px;
      }

      .cta {
        margin-top: 22px;
        display: inline-flex;
        align-items: center;
        gap: 10px;
        padding: 14px 18px;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--primary), var(--secondary));
        color: #06101c;
        font-size: 13px;
        font-weight: 800;
        letter-spacing: 0.18em;
        text-transform: uppercase;
      }

      @media (max-width: 720px) {
        .frame {
          min-height: 100vh;
          border-radius: 0;
          width: 100vw;
          padding: 18px;
        }

        .meter {
          grid-template-columns: 1fr;
        }
      }
    </style>
  </head>
  <body>
    <div class="frame">
      <div class="glow one"></div>
      <div class="glow two"></div>
      <div class="topline">
        <span class="badge">Playable Preview</span>
        <span class="badge">${escapeHtml(game.genre)}</span>
      </div>
      <div class="hud">
        <div class="meter">
          <div>
            <span>Session</span>
            <strong>${escapeHtml(game.sessionLabel)}</strong>
          </div>
          <div>
            <span>Catalog role</span>
            <strong>${escapeHtml(game.slot)}</strong>
          </div>
          <div>
            <span>Status</span>
            <strong>${escapeHtml(game.status)}</strong>
          </div>
        </div>
        <div class="panel">
          <h1>${escapeHtml(game.title)}</h1>
          <p>${escapeHtml(game.tagline)}</p>
          <div class="tag-row">${tagMarkup}</div>
          <ul class="controls">${controlsMarkup}</ul>
          <div class="cta">Swap this srcDoc for your real HTML5 build</div>
        </div>
      </div>
    </div>
  </body>
</html>`
}

function GamePlayerFrame({ game }) {
  return (
    <div className="arcade-panel overflow-hidden">
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[rgba(27,28,49,0.08)] px-5 py-4 sm:px-6">
        <div>
          <p className="text-[10px] font-bold uppercase tracking-[0.28em] text-slate-500">
            Play stage
          </p>
          <h2 className="mt-2 text-xl font-bold text-slate-900 sm:text-2xl">
            iframe-ready game surface
          </h2>
        </div>
        <span className="rounded-full bg-[#1b1c31] px-3 py-1 text-[10px] font-bold uppercase tracking-[0.22em] text-white">
          16:10 frame
        </span>
      </div>
      <div className="aspect-[16/10] bg-[#0d1120]">
        <iframe
          title={`${game.title} preview frame`}
          srcDoc={buildPreviewSrcDoc(game)}
          className="h-full w-full border-0"
          loading="lazy"
        />
      </div>
      <p className="px-5 py-4 text-sm leading-7 text-slate-600 sm:px-6">
        This is a drop-in iframe slot. Replace the preview `srcDoc` with your deployed HTML5 game build,
        partner embed, or a local build artifact when the real game is ready.
      </p>
    </div>
  )
}

export default GamePlayerFrame
